//! OpenAPI 3.1 spec for the admin JSON API.
//!
//! The spec covers `/v1/admin/*` only — the mTLS runtime API
//! (`/v1/wrappers`, `/v1/wrapper-invocations*`) is an internal
//! daemon-to-backend contract and intentionally absent here.
//!
//! The spec is the source of truth for the operator SPA's API client
//! (see ticket 1750). It is regenerated by the
//! `openapi_spec_round_trips` drift test in `tests/openapi_export.rs`
//! and committed to `crates/backend-backendd/openapi.json`.

use utoipa::Modify;
use utoipa::OpenApi;
use utoipa::openapi::security::{ApiKey, ApiKeyValue, SecurityScheme};

/// OpenAPI 3.1 document including the live admin path table. Used by
/// the drift test in `tests/openapi_export.rs` and by future tooling
/// that wants to consume the spec directly.
pub fn admin_openapi_spec() -> utoipa::openapi::OpenApi {
    crate::admin_api::admin_openapi_spec()
}

/// Top-level OpenAPI document. Subdomain routers are added by the
/// `admin_api::admin_router` builder via `utoipa-axum`'s
/// `OpenApiRouter::routes(..)` calls; this struct just sets the metadata
/// envelope (info, security schemes, tags).
#[derive(OpenApi)]
#[openapi(
    info(
        title = "underwrap admin API",
        description = "Operator-facing JSON API exposed by `underwrap-backendd` under `/v1/admin/*`. \
                       Authentication is session-cookie based (`__Host-uw-session`); \
                       state-changing requests must also carry the synchronizer CSRF \
                       header `X-CSRF-Token`. The mTLS runtime API is not part of this \
                       contract.",
        version = "0.1.0",
        license(name = "MIT OR Apache-2.0"),
    ),
    modifiers(&SecurityAddon),
    tags(
        (name = "auth",            description = "Login, logout, whoami, password change."),
        (name = "bootstrap",       description = "First-time operator setup."),
        (name = "overview",        description = "Overview / dashboard data."),
        (name = "users",           description = "Operator collection CRUD."),
        (name = "stores",          description = "Store registry CRUD + lifecycle."),
        (name = "client_instances",description = "Runtime client-instance registry."),
        (name = "resources",       description = "Per-store resource records."),
        (name = "pairs",           description = "Wrapper ↔ resource pairs."),
        (name = "secrets",         description = "Encrypted resource blob slots."),
        (name = "policy",          description = "Per-store policy document."),
    ),
)]
pub struct ApiDoc;

/// Registers the two SecuritySchemes referenced by individual handler
/// annotations: the session cookie (required for every protected
/// endpoint) and the CSRF synchronizer-token header (additionally
/// required on state-changing methods).
struct SecurityAddon;

impl Modify for SecurityAddon {
    fn modify(&self, openapi: &mut utoipa::openapi::OpenApi) {
        let components = openapi
            .components
            .as_mut()
            .expect("derive should populate components");
        components.add_security_scheme(
            "session_cookie",
            SecurityScheme::ApiKey(ApiKey::Cookie(ApiKeyValue::new("__Host-uw-session"))),
        );
        components.add_security_scheme(
            "csrf_header",
            SecurityScheme::ApiKey(ApiKey::Header(ApiKeyValue::new("X-CSRF-Token"))),
        );
    }
}
